package com.tencent.weknora.security;
import java.nio.file.*;import java.util.*;import org.springframework.core.env.Environment;import org.springframework.stereotype.Component;import org.yaml.snakeyaml.*;import org.yaml.snakeyaml.constructor.SafeConstructor;
/** Shares Go's configured built-in identity set; ID spelling alone is not a built-in marker. */
@Component public final class BuiltinAgentRegistry {
 private final Set<String> ids;
 public BuiltinAgentRegistry(Environment environment){String configured=environment.getProperty("weknora.go-config-path",environment.getProperty("JAVA_GO_CONFIG"));List<Path> configs=configured==null?List.of(Path.of("config.yaml"),Path.of("config/config.yaml"),Path.of("../config/config.yaml")):List.of(Path.of(configured));Path parent=Path.of(".");for(Path config:configs)if(Files.isRegularFile(config)){parent=config.toAbsolutePath().getParent();break;}ids=load(parent.resolve("builtin_agents.yaml"));}
 public Set<String> ids(){return ids;}
 static Set<String> load(Path path){if(!Files.exists(path))return Set.of();try(var input=Files.newInputStream(path)){Object document=new Yaml(new SafeConstructor(new LoaderOptions())).load(input);if(document==null)return Set.of();if(!(document instanceof Map<?,?> map))throw new IllegalArgumentException("builtin_agents config must be a map");Object entries=map.get("builtin_agents");if(entries==null)return Set.of();if(!(entries instanceof List<?> list))throw new IllegalArgumentException("builtin_agents must be an array");Set<String> out=new LinkedHashSet<>();for(Object entry:list){if(entry==null)continue;if(!(entry instanceof Map<?,?> fields))throw new IllegalArgumentException("builtin_agent entry must be a map");Object id=fields.get("id");if(id!=null&&!(id instanceof String))throw new IllegalArgumentException("builtin agent id must be a string");out.add(id==null?"":id.toString());}return Set.copyOf(out);}catch(Exception ex){throw new IllegalStateException("Cannot load built-in agent identities from "+path,ex);}}
}
